#!/usr/bin/env python3
"""Assemble concise review tables from metrics; never reads the blind key."""
import collections,json,pathlib,statistics
B=pathlib.Path('/data/coding/scanweave/work/books01');P=pathlib.Path(__file__).resolve().parents[1];Q=P/'pilot'
def load(n):return json.loads((Q/'results'/n).read_text())
size=load('text-and-size.json');vis=load('visual.json');perf=load('performance.json');eq=load('path-equivalence.json');align=load('alignment.json');tri=load('triage.json');search=load('search-layout.json');repeat=load('adobe-repeat.json');neg=load('negative-shim.json');frozen=load('frozen-ocr-index.json');ids=json.loads((P/'corpus.frozen.json').read_text())['pilot_6'];locks=json.loads((P/'sources.lock.json').read_text())['pages']
def num(x,n=3):return '—' if x is None else f'{x:.{n}f}'
def pagename(id):return id.split('/')[-1]+(' (low DPI confidence)' if locks[id]['dpi_evidence']['confidence']=='low' else '')
rows=['src','sw-E','sw-M','sw-build','ocrmypdf-E','mrc-M','adobe-E'];s=['# BOOKS-01 Phase 1: six-page pilot','','The six frozen pilot pages were run. Holdout and other dev pages were not run. Existing Adobe files were ingested only. See `track-matrix.md`, `versions.json`, `methodology.md` and `results/` for methods, versions and machine-readable rows. No final smallest-acceptable ranking is made.','','## Size (bytes)','','| Pilot page | '+ ' | '.join(rows)+' |','|---|'+ '---:|'*len(rows)]
for id in ids:s.append('| '+pagename(id)+' | '+' | '.join(str(size[id]['rows'][r].get('size',{}).get('file_bytes','—')) for r in rows)+' |')
s+=['','## OCR versus extraction','','Reading CER uses known-character denominator with U+FFFD wildcards, and includes reading-order errors. It does not measure visual reconstruction. Frozen hOCR is the matched pre-PDF OCR.','', '| Pilot page | Known chars | U+FFFD | Frozen hOCR CER | sw-M PDFium CER | Adobe PDFium CER |','|---|---:|---:|---:|---:|---:|']
for id in ids:
 r=size[id];f=r['frozen_hocr_scores']['reading'];extract=lambda row:r['rows'][row].get('extraction',{}).get('pdfium',{}).get('scores',{}).get('reading',{}).get('cer');s.append(f"| {pagename(id)} | {f['known_characters']} | {f['unknown_characters']} | {num(f['cer'])} | {num(extract('sw-M'))} | {num(extract('adobe-E'))} |")
s+=['','## Visual fidelity at source DPI, PDFium','','Values are text-region SSIM / ink recall; a dash means no measurable denominator. These are automated measurements, not confirmed defect counts. Full renderer, resolution, class, ΔL, colour and precision data are in `results/visual.json`.','', '| Pilot page | sw-E | OCRmyPDF | MRC | Adobe |','|---|---:|---:|---:|---:|']
for id in ids:
 dpi=str(int(locks[id]['resolved_dpi']))
 def val(row):
  v=vis[id][row]['pdfium'][dpi]; t=v.get('regions',{}).get('text',{});return num(t.get('ssim'))+' / '+num(t.get('ink_recall'))
 s.append('| '+pagename(id)+' | '+' | '.join(val(r) for r in ['sw-E','ocrmypdf-E','mrc-M','adobe-E'])+' |')
s+=['','## Conversion wall time (seconds)','','Adobe timing includes GUI sleeps and startup and is not comparable to CLI times. Per-row CPU, peak RSS and renderer timing distributions are in `results/performance.json` and `results/render-costs.json`.','', '| Pilot page | sw-E | sw-M | sw-build | OCRmyPDF | MRC | Adobe GUI |','|---|---:|---:|---:|---:|---:|---:|']
for id in ids:s.append('| '+pagename(id)+' | '+' | '.join(num(perf['pages'][id]['rows'][r].get('wall_seconds'),1) for r in ['sw-E','sw-M','sw-build','ocrmypdf-E','mrc-M','adobe-E'])+' |')
s+=['','## Path comparison','','Stock PDF import uses internal OCR and `convert_document_with_sources_and_sharing` with source images; `build --ocr --profile clearscan` calls single-page `convert` without source images and is diagnostic only. All six sw-E and sw-M PDF bytes match. Raw hOCR differs on all six only because the input image path embedded in hOCR differs; after redacting that field, all match. PSM 3 and PSM 6 frozen OCR were each deterministic in repeated runs. The shim checks pixel hash, exact arguments and call order. All three negative tests rejected their input and produced no PDF.','', '| Pilot page | sw-M bytes | build bytes | PDF bytes equal? | Extracted text equal? | Changed rendered pixels at 150 DPI |','|---|---:|---:|---|---|---:|']
for id in ids:
 v=eq[id]['sw_M_vs_build'];s.append(f"| {pagename(id)} | {v['pdf_bytes_M']} | {v['pdf_bytes_build']} | {v['pdf_byte_equal']} | {v['extracted_text_equal']} | {num(v['changed_pixel_fraction'],6)} |")
s+=['','## Alignment and triage','','FineBooks has no GT TextLines. Single-line TextRegions are proxies only; their coverage is reported below, with region-level metrics for the remainder. OCR overlap uses word-box centres. Alignment overlays and the blind pack are local under `$B/qa/pilot-alignment/` and `$B/pilot/blind/`.','', '| Pilot page | GT geometry | Lines / proxies | Known chars covered | OCR word centres inside |','|---|---|---:|---:|---:|']
for id in ids:
 a=align[id];s.append(f"| {pagename(id)} | {a['type']} | {a['line_or_proxy_count']} | {a['known_characters_covered']} | {num(a['ocr_word_centre_fraction'])} |")
s += ['',f"The blind pack contains {tri['crop_count']} crops; top candidates and random controls are identified only as suspected or controls. Per-page 99.5th-percentile score distributions are in `results/triage.json`; raw scores are local. Confirmed defects are **not yet adjudicated**, rather than zero.",'', 'The first OCRmyPDF attempt on Luther failed because the isolated Tesseract directory lacked its `txt` config; the unchanged system config was added, hashed, and that page was retried successfully. The Adobe repeat PDFs have identical Poppler-extracted text on all six pages and size differences of at most one byte. The GUI wall times are not CLI benchmarks. Claude’s offline logs record 104 and 198 refused Wine service-thread internet-socket attempts in the current and superseded batches respectively; no Adobe process was started here.','', '## Costs and readiness','',f"Logical disk bytes by pilot stage: {perf['logical_disk_bytes_by_stage']}. Renderer timings use five warm runs after a warm-up; p95 is nearest-rank, hence the maximum of five. GNU time records CPU and peak RSS for commands. Poppler uses CropBox where the PDF has a distinct CropBox; the other PDFs have equal page boxes. Earlier abandoned MediaBox and CropBox rerender attempts are not completely attributed in the per-row cost totals.",'', f"The six-page sequential CLI totals by row are {perf['six_page_cli_wall_seconds_by_row']}; multiplying these measured values by six gives {perf['linear_36_page_projection_seconds_by_row']} seconds. This is a linear projection, not a runtime guarantee; Adobe is excluded.",'', 'Recommendation: **not ready to run all 36 pages yet**. Claude must adjudicate the blinded candidates and the owner must review the proposed acceptance thresholds. FineBooks proxy coverage varies; the simple PDFium line grouper can merge columns; exact-text Kendall tau excludes unmatched lines; byte attribution leaves dictionary/xref/other bytes in a reconciled residual and cannot isolate compressed text-layer bytes from other page-content bytes. OCRmyPDF’s lossless source retention is a control, not proof that other rows preserve visible glyphs.','', 'Open items: the reading-normalization rules follow the approved spec but were not independently checked against the external FineBooks evaluator; the Phase 0 low-confidence DPI remains accepted for this pilot, not validated; some tool and measurement startup/aborted-attempt costs are not fully captured. No Adobe or Wine process was run.','']
(Q/'PHASE1.md').write_text('\n'.join(s))
# An intentionally provisional rule for owner review, never a Phase 1 ranking.
controls=[]
for id in ids:
 dpi=str(int(locks[id]['resolved_dpi']));t=vis[id]['ocrmypdf-E']['pdfium'][dpi]['regions']['text'];controls.append((t['ssim'],t['ink_recall']))
ss=[x for x,y in controls if x is not None];ink=[y for x,y in controls if y is not None]
a=['# Proposed acceptance rule — owner review required','','Do not rank outputs in this pilot. A page would be eligible only if all applicable checks pass:','','1. Independent adjudication confirms no wrong-character shape, missing-ink or border-inversion defect on the sampled material; all material suspected candidates must be resolved. Absence of a sampled finding is not proof of absence.','2. At each declared renderer and resolution, text-region SSIM ≥ 0.98 and ink recall ≥ 0.99; paper SSIM ≥ 0.98; illustration SSIM ≥ 0.98 when a region exists. Undefined metrics are not automatic passes. Also review ΔL, ΔE2000, ink precision and sampled colour/halo candidates.','3. Reading-normalized PDFium extraction CER is no more than 0.05 absolute above the selected frozen-hOCR CER, using the known-character denominator and wildcard rules in `methodology.md`. Literal PDFium search hits at least 10 of the 20 sampled eligible GT terms; fewer than 20 terms use the same 50% floor. Adobe is evaluated separately because its OCR language is unmatched.','',f"Justification and limits: the OCRmyPDF visual control’s PDFium source-DPI text SSIM range is {min(ss):.6f}–{max(ss):.6f}, and ink recall range is {min(ink):.6f}–{max(ink):.6f} over these six pages. The proposed floors allow small deviations from that control; they are not established perceptual pass limits. Search and CER tolerances are initial engineering proposals, not statistical guarantees. The six-page pilot and non-adjudicated detector output are insufficient to validate these limits. Owner review and blinded human findings are required before freezing them.",'']
(Q/'acceptance-proposal.md').write_text('\n'.join(a))
